module horizontal_counter
   (E,
    Q,
    \h_count_reg[8]_0 ,
    \h_count_reg[6]_0 ,
    CLK,
    \blue_reg[2] ,
    locked,
    \blue_reg[2]_0 ,
    rst_IBUF);
  output [0:0]E;
  output [8:0]Q;
  output \h_count_reg[8]_0 ;
  output \h_count_reg[6]_0 ;
  input CLK;
  input \blue_reg[2] ;
  input locked;
  input [0:0]\blue_reg[2]_0 ;
  input rst_IBUF;

  wire CLK;
  wire [0:0]E;
  wire [8:0]Q;
  wire \blue_reg[2] ;
  wire [0:0]\blue_reg[2]_0 ;
  wire enable_v_count_i_1_n_1;
  wire \h_count[6]_i_2_n_1 ;
  wire \h_count[8]_i_2_n_1 ;
  wire \h_count[9]_i_1_n_1 ;
  wire \h_count[9]_i_3_n_1 ;
  wire \h_count[9]_i_4_n_1 ;
  wire [0:0]h_count__0;
  wire \h_count_reg[6]_0 ;
  wire \h_count_reg[8]_0 ;
  wire hsync_reg_inv_i_2_n_1;
  wire locked;
  wire [9:0]p_0_in;
  wire rst_IBUF;

  LUT3 #(
    .INIT(8'h20)) 
    enable_v_count_i_1
       (.I0(\h_count[9]_i_3_n_1 ),
        .I1(rst_IBUF),
        .I2(locked),
        .O(enable_v_count_i_1_n_1));
  FDRE #(
    .INIT(1'b0)) 
    enable_v_count_reg
       (.C(CLK),
        .CE(1'b1),
        .D(enable_v_count_i_1_n_1),
        .Q(E),
        .R(1'b0));
  LUT1 #(
    .INIT(2'h1)) 
    \h_count[0]_i_1 
       (.I0(h_count__0),
        .O(p_0_in[0]));
  (* SOFT_HLUTNM = "soft_lutpair65" *) 
  LUT2 #(
    .INIT(4'h6)) 
    \h_count[1]_i_1 
       (.I0(Q[0]),
        .I1(h_count__0),
        .O(p_0_in[1]));
  (* SOFT_HLUTNM = "soft_lutpair65" *) 
  LUT3 #(
    .INIT(8'h6A)) 
    \h_count[2]_i_1 
       (.I0(Q[1]),
        .I1(h_count__0),
        .I2(Q[0]),
        .O(p_0_in[2]));
  (* SOFT_HLUTNM = "soft_lutpair63" *) 
  LUT4 #(
    .INIT(16'h6AAA)) 
